import{_ as t,c as e,o as r,a5 as n}from"./chunks/framework.DorIfSpC.js";const u=JSON.parse('{"title":"從零理解神經網路：完整系列導覽","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/learning/micrograd_visualize/00-overview"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/learning/micrograd_visualize/00-overview"}],["meta",{"property":"og:title","content":"從零理解神經網路：完整系列導覽 | 星智未來"}],["meta",{"name":"twitter:title","content":"從零理解神經網路：完整系列導覽 | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"從零理解神經網路：完整系列導覽\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/learning/micrograd_visualize/00-overview\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/learning/micrograd_visualize/00-overview\\"}}"]]},"headers":[],"relativePath":"learning/micrograd_visualize/00-overview.md","filePath":"learning/micrograd_visualize/00-overview.md","lastUpdated":1773991828000}'),l={name:"learning/micrograd_visualize/00-overview.md"};function i(s,a,o,p,h,d){return r(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="從零理解神經網路-完整系列導覽" tabindex="-1">從零理解神經網路：完整系列導覽 <a class="header-anchor" href="#從零理解神經網路-完整系列導覽" aria-label="Permalink to &quot;從零理解神經網路：完整系列導覽&quot;">​</a></h1><blockquote><p>這是一個為期 6 篇的深度學習入門系列。我們會從最基本的神經元開始，一步步建立起對神經網路的完整理解——不只是會用，而是真正懂它在做什麼。</p></blockquote><p><strong>作者</strong>：Ray <strong>日期</strong>：2025 年 12 月 31 日</p><hr><h2 id="為什麼寫這個系列" tabindex="-1">為什麼寫這個系列？ <a class="header-anchor" href="#為什麼寫這個系列" aria-label="Permalink to &quot;為什麼寫這個系列？&quot;">​</a></h2><p>學習深度學習時，很多人會遇到這樣的困境：</p><ul><li>📚 <strong>教科書太硬</strong>：滿滿的數學推導，看不到直覺</li><li>🎥 <strong>影片太軟</strong>：看完好像懂了，但自己推導不出來</li><li>💻 <strong>框架太黑盒</strong>：會呼叫 API，但不知道背後發生什麼事</li></ul><p>這個系列試圖找到平衡點：<strong>用直覺理解數學，用數學支撐直覺</strong>。</p><p>每篇文章都配有互動視覺化工具，讓你能「玩」出對概念的理解。</p><h2 id="這個系列適合誰" tabindex="-1">這個系列適合誰？ <a class="header-anchor" href="#這個系列適合誰" aria-label="Permalink to &quot;這個系列適合誰？&quot;">​</a></h2><p>✅ 想入門機器學習，但被數學嚇到的人<br> ✅ 會用 PyTorch/TensorFlow，但想搞懂原理的人<br> ✅ 準備面試，需要解釋反向傳播的人<br> ✅ 喜歡從第一原理理解事物的人</p><h2 id="先備知識" tabindex="-1">先備知識 <a class="header-anchor" href="#先備知識" aria-label="Permalink to &quot;先備知識&quot;">​</a></h2><ul><li><strong>高中數學</strong>：函數、導數的基本概念</li><li><strong>一點 Python</strong>：能看懂簡單的程式碼</li><li><strong>好奇心</strong>：這是最重要的 ✨</li></ul><p>不需要線性代數或微積分的深厚背景——我們會在需要時解釋。</p><hr><h2 id="📚-系列文章" tabindex="-1">📚 系列文章 <a class="header-anchor" href="#📚-系列文章" aria-label="Permalink to &quot;📚 系列文章&quot;">​</a></h2><h3 id="第一篇-一個神經元是如何思考的" tabindex="-1">第一篇：一個神經元是如何思考的？ <a class="header-anchor" href="#第一篇-一個神經元是如何思考的" aria-label="Permalink to &quot;第一篇：一個神經元是如何思考的？&quot;">​</a></h3><blockquote><p><strong>核心問題</strong>：神經網路的最小單元是什麼？它怎麼運作？</p></blockquote><p>我們從生物神經元的啟發開始，理解人工神經元的數學模型：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>輸出 = 激活函數( w₁x₁ + w₂x₂ + w₃x₃ + b )</span></span></code></pre></div><p>你會學到：</p><ul><li>權重（weights）如何決定輸入的重要性</li><li>偏置（bias）為什麼像是「預設傾向」</li><li>單個神經元的能力與局限</li></ul><p>👉 <a href="./01-multi-input-neuron">閱讀文章</a> ｜ 🎮 <a href="/htmls/multi-input-neuron.html" target="_blank">互動視覺化</a></p><hr><h3 id="第二篇-為什麼激活函數如此重要" tabindex="-1">第二篇：為什麼激活函數如此重要？ <a class="header-anchor" href="#第二篇-為什麼激活函數如此重要" aria-label="Permalink to &quot;第二篇：為什麼激活函數如此重要？&quot;">​</a></h3><blockquote><p><strong>核心問題</strong>：如果沒有激活函數，100 層網路跟 1 層有什麼差別？</p></blockquote><p>這篇揭示一個驚人的數學事實：純線性網路不管多深，都等於單層。</p><p>你會學到：</p><ul><li>為什麼線性組合的線性組合還是線性</li><li>XOR 問題如何展示線性模型的局限</li><li>ReLU、Sigmoid、Tanh 各自的特點與適用場景</li><li>梯度消失問題是怎麼回事</li></ul><p>👉 <a href="./02-activation-functions">閱讀文章</a> ｜ 🎮 <a href="/htmls/activation-functions.html" target="_blank">互動視覺化</a></p><hr><h3 id="第三篇-梯度下降——順著山坡找谷底" tabindex="-1">第三篇：梯度下降——順著山坡找谷底 <a class="header-anchor" href="#第三篇-梯度下降——順著山坡找谷底" aria-label="Permalink to &quot;第三篇：梯度下降——順著山坡找谷底&quot;">​</a></h3><blockquote><p><strong>核心問題</strong>：神經網路的權重是怎麼「學」出來的？</p></blockquote><p>把損失函數想像成一個地形，訓練就是找到最低點。</p><p>你會學到：</p><ul><li>損失函數如何衡量「錯得有多離譜」</li><li>梯度為什麼指向「上坡」方向</li><li>學習率太大或太小會怎樣</li><li>SGD、Momentum、Adam 的差異</li></ul><p>👉 <a href="./03-gradient-descent">閱讀文章</a> ｜ 🎮 <a href="/htmls/gradient-descent-3d.html" target="_blank">互動視覺化</a></p><hr><h3 id="第四篇-反向傳播——誰該為錯誤負責" tabindex="-1">第四篇：反向傳播——誰該為錯誤負責？ <a class="header-anchor" href="#第四篇-反向傳播——誰該為錯誤負責" aria-label="Permalink to &quot;第四篇：反向傳播——誰該為錯誤負責？&quot;">​</a></h3><blockquote><p><strong>核心問題</strong>：怎麼算出每個權重該調整多少？</p></blockquote><p>用「傳話遊戲」的比喻，理解深度學習最核心的算法。</p><p>你會學到：</p><ul><li>鏈式法則如何讓梯度「一層層傳回去」</li><li>為什麼反向傳播比暴力方法快數百萬倍</li><li>每層如何只需要「局部資訊」就能計算梯度</li><li>梯度消失和梯度爆炸是怎麼發生的</li></ul><p>👉 <a href="./04-backpropagation">閱讀文章</a> ｜ 🎮 <a href="/htmls/backprop-complete.html" target="_blank">互動視覺化</a></p><hr><h3 id="第五篇-計算圖——為什麼叫「自動」微分" tabindex="-1">第五篇：計算圖——為什麼叫「自動」微分？ <a class="header-anchor" href="#第五篇-計算圖——為什麼叫「自動」微分" aria-label="Permalink to &quot;第五篇：計算圖——為什麼叫「自動」微分？&quot;">​</a></h3><blockquote><p><strong>核心問題</strong>：PyTorch 怎麼自動幫我算梯度的？</p></blockquote><p>揭開深度學習框架的核心魔法——計算圖。</p><p>你會學到：</p><ul><li>計算圖是什麼（有向無環圖 DAG）</li><li>前向傳播如何「記錄」運算歷史</li><li>反向傳播如何沿著圖「回溯」</li><li>micrograd 的 50 行核心程式碼解析</li></ul><p>👉 <a href="./05-computation-graph">閱讀文章</a> ｜ 🎮 <a href="/htmls/computation-graph.html" target="_blank">互動視覺化</a></p><hr><h3 id="第六篇-實戰——訓練你的第一個神經網路" tabindex="-1">第六篇：實戰——訓練你的第一個神經網路 <a class="header-anchor" href="#第六篇-實戰——訓練你的第一個神經網路" aria-label="Permalink to &quot;第六篇：實戰——訓練你的第一個神經網路&quot;">​</a></h3><blockquote><p><strong>核心問題</strong>：把所有概念組合起來，會發生什麼？</p></blockquote><p>親眼看神經網路如何從「亂猜」變成「學會」。</p><p>你會學到：</p><ul><li>MLP（多層感知器）的結構</li><li>完整的訓練迴圈：前向 → 損失 → 反向 → 更新</li><li>決策邊界如何隨訓練演化</li><li>超參數（學習率、網路深度）的影響</li><li>常見問題的診斷與解決</li></ul><p>👉 <a href="./06-mlp-training">閱讀文章</a> ｜ 🎮 <a href="/htmls/mlp-trainer.html" target="_blank">互動視覺化</a></p><hr><h2 id="🎮-互動視覺化工具" tabindex="-1">🎮 互動視覺化工具 <a class="header-anchor" href="#🎮-互動視覺化工具" aria-label="Permalink to &quot;🎮 互動視覺化工具&quot;">​</a></h2><p>每篇文章都配有對應的互動工具，讓你能動手實驗：</p><table tabindex="0"><thead><tr><th>工具</th><th>功能</th><th>建議實驗</th></tr></thead><tbody><tr><td><a href="/htmls/multi-input-neuron.html" target="_blank">多輸入神經元</a></td><td>調整權重和偏置，看輸出變化</td><td>把某個權重調成負的，觀察效果</td></tr><tr><td><a href="/htmls/activation-functions.html" target="_blank">激活函數</a></td><td>比較不同激活函數的形狀和導數</td><td>觀察 Sigmoid 在極端值時梯度多小</td></tr><tr><td><a href="/htmls/gradient-descent-3d.html" target="_blank">梯度下降 3D</a></td><td>在 3D 損失地形上嘗試優化</td><td>用不同學習率，觀察收斂行為</td></tr><tr><td><a href="/htmls/backprop-complete.html" target="_blank">反向傳播</a></td><td>追蹤梯度如何一層層傳遞</td><td>觀察哪一層「責任」最大</td></tr><tr><td><a href="/htmls/computation-graph.html" target="_blank">計算圖</a></td><td>看運算如何形成圖結構</td><td>點擊節點看數值和梯度</td></tr><tr><td><a href="/htmls/mlp-trainer.html" target="_blank">MLP 訓練器</a></td><td>即時訓練神經網路，看決策邊界</td><td>用螺旋資料集，試不同網路結構</td></tr></tbody></table><hr><h2 id="🗺️-概念地圖" tabindex="-1">🗺️ 概念地圖 <a class="header-anchor" href="#🗺️-概念地圖" aria-label="Permalink to &quot;🗺️ 概念地圖&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    神經網路的運作原理</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>        ┌──────────────────┼──────────────────┐</span></span>
<span class="line"><span>        │                  │                  │</span></span>
<span class="line"><span>        ▼                  ▼                  ▼</span></span>
<span class="line"><span>    【結構】            【學習】            【實現】</span></span>
<span class="line"><span>        │                  │                  │</span></span>
<span class="line"><span>   ┌────┴────┐        ┌────┴────┐        ┌────┴────┐</span></span>
<span class="line"><span>   │         │        │         │        │         │</span></span>
<span class="line"><span>   ▼         ▼        ▼         ▼        ▼         ▼</span></span>
<span class="line"><span> 神經元   激活函數   梯度下降  反向傳播   計算圖   MLP訓練</span></span>
<span class="line"><span> (第1篇)  (第2篇)   (第3篇)   (第4篇)   (第5篇)  (第6篇)</span></span>
<span class="line"><span>   │         │        │         │        │         │</span></span>
<span class="line"><span>   └────┬────┘        └────┬────┘        └────┬────┘</span></span>
<span class="line"><span>        │                  │                  │</span></span>
<span class="line"><span>        ▼                  ▼                  ▼</span></span>
<span class="line"><span>   「網路能表達      「網路能找到        「框架自動</span></span>
<span class="line"><span>    複雜函數」        最佳參數」         處理一切」</span></span></code></pre></div><hr><h2 id="📖-建議閱讀方式" tabindex="-1">📖 建議閱讀方式 <a class="header-anchor" href="#📖-建議閱讀方式" aria-label="Permalink to &quot;📖 建議閱讀方式&quot;">​</a></h2><h3 id="方式一-循序漸進-推薦新手" tabindex="-1">方式一：循序漸進（推薦新手） <a class="header-anchor" href="#方式一-循序漸進-推薦新手" aria-label="Permalink to &quot;方式一：循序漸進（推薦新手）&quot;">​</a></h3><p>按順序閱讀，每篇花 20-30 分鐘：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第1篇 → 第2篇 → 第3篇 → 第4篇 → 第5篇 → 第6篇</span></span>
<span class="line"><span>  │       │       │       │       │       │</span></span>
<span class="line"><span>  └───────┴───────┴───────┴───────┴───────┘</span></span>
<span class="line"><span>              每篇建立在前一篇基礎上</span></span></code></pre></div><h3 id="方式二-主題跳讀-有基礎者" tabindex="-1">方式二：主題跳讀（有基礎者） <a class="header-anchor" href="#方式二-主題跳讀-有基礎者" aria-label="Permalink to &quot;方式二：主題跳讀（有基礎者）&quot;">​</a></h3><p>根據你的需求選擇：</p><ul><li><strong>想懂網路結構</strong>：第 1 篇 → 第 2 篇</li><li><strong>想懂訓練原理</strong>：第 3 篇 → 第 4 篇</li><li><strong>想懂框架實現</strong>：第 5 篇</li><li><strong>想看完整實戰</strong>：第 6 篇</li></ul><h3 id="方式三-互動優先" tabindex="-1">方式三：互動優先 <a class="header-anchor" href="#方式三-互動優先" aria-label="Permalink to &quot;方式三：互動優先&quot;">​</a></h3><p>直接打開視覺化工具玩，遇到不懂的再回去看文章。</p><hr><h2 id="❓-常見問題" tabindex="-1">❓ 常見問題 <a class="header-anchor" href="#❓-常見問題" aria-label="Permalink to &quot;❓ 常見問題&quot;">​</a></h2><h3 id="q-我數學很差-看得懂嗎" tabindex="-1">Q：我數學很差，看得懂嗎？ <a class="header-anchor" href="#q-我數學很差-看得懂嗎" aria-label="Permalink to &quot;Q：我數學很差，看得懂嗎？&quot;">​</a></h3><p>這個系列刻意避免複雜的數學推導，用圖示和比喻來解釋概念。如果你懂「斜率」的概念，就能跟上大部分內容。</p><h3 id="q-看完這個系列-我能做什麼" tabindex="-1">Q：看完這個系列，我能做什麼？ <a class="header-anchor" href="#q-看完這個系列-我能做什麼" aria-label="Permalink to &quot;Q：看完這個系列，我能做什麼？&quot;">​</a></h3><ul><li>✅ 理解神經網路的運作原理</li><li>✅ 看懂 PyTorch/TensorFlow 程式碼在做什麼</li><li>✅ 在面試中解釋反向傳播</li><li>✅ 有基礎繼續學 CNN、RNN、Transformer</li></ul><h3 id="q-這個系列和-andrej-karpathy-的-micrograd-什麼關係" tabindex="-1">Q：這個系列和 Andrej Karpathy 的 micrograd 什麼關係？ <a class="header-anchor" href="#q-這個系列和-andrej-karpathy-的-micrograd-什麼關係" aria-label="Permalink to &quot;Q：這個系列和 Andrej Karpathy 的 micrograd 什麼關係？&quot;">​</a></h3><p>micrograd 是 Karpathy 寫的教學用自動微分引擎，這個系列的視覺化工具就是把 micrograd 的核心概念做成互動版。強烈建議看完這個系列後，去看 Karpathy 的 <a href="https://www.youtube.com/watch?v=VMj-3S1tku0" target="_blank" rel="noreferrer">micrograd 影片</a>。</p><h3 id="q-接下來該學什麼" tabindex="-1">Q：接下來該學什麼？ <a class="header-anchor" href="#q-接下來該學什麼" aria-label="Permalink to &quot;Q：接下來該學什麼？&quot;">​</a></h3><ul><li><strong>CNN</strong>：圖像識別（推薦 CS231n）</li><li><strong>RNN/Transformer</strong>：自然語言處理</li><li><strong>實戰專案</strong>：Kaggle 競賽</li><li><strong>進階數學</strong>：線性代數、機率論</li></ul><hr><h2 id="🙏-致謝" tabindex="-1">🙏 致謝 <a class="header-anchor" href="#🙏-致謝" aria-label="Permalink to &quot;🙏 致謝&quot;">​</a></h2><p>這個系列的靈感和知識來自：</p><ul><li><a href="https://karpathy.ai/" target="_blank" rel="noreferrer">Andrej Karpathy</a> 的 micrograd 和教學影片</li><li><a href="https://www.3blue1brown.com/" target="_blank" rel="noreferrer">3Blue1Brown</a> 的神經網路視覺化</li><li><a href="http://cs231n.stanford.edu/" target="_blank" rel="noreferrer">Stanford CS231n</a> 課程</li><li><a href="https://stanford-cs336.github.io/spring2025/" target="_blank" rel="noreferrer">Stanford CS336</a> 課程</li></ul><hr><h2 id="開始吧" tabindex="-1">開始吧！ <a class="header-anchor" href="#開始吧" aria-label="Permalink to &quot;開始吧！&quot;">​</a></h2><p>準備好了嗎？讓我們從第一篇開始：</p><p>👉 <strong><a href="./01-multi-input-neuron">第一篇：一個神經元是如何思考的？</a></strong></p><hr><p><em>如果這個系列對你有幫助，歡迎分享給也在學習的朋友。有問題或建議，歡迎留言討論！</em></p>`,95)])])}const g=t(l,[["render",i]]);export{u as __pageData,g as default};
